/**
 * <picture> with AVIF/WebP variants generated by scripts/optimize-images.mjs.
 *
 * Provide the original image path as `base` and the generated widths; variants
 * are expected next to it (e.g. '/assets/logo_te.jpg' + [400] ->
 * '/assets/logo_te-400.avif' and '/assets/logo_te-400.webp'). The original
 * file remains the fallback for browsers without modern format support.
 */
export const ResponsivePicture = ({
  base,
  widths = [],
  sizes,
  alt,
  className,
  width,
  height,
  loading,
  fetchPriority,
  decoding,
  onError,
}) => {
  const stem = base.replace(/\.(png|jpe?g)$/i, '');
  const makeSrcSet = (ext) => widths.map((w) => `${stem}-${w}.${ext} ${w}w`).join(', ');

  return (
    <picture>
      {widths.length > 0 && (
        <source type="image/avif" srcSet={makeSrcSet('avif')} sizes={sizes} />
      )}
      {widths.length > 0 && (
        <source type="image/webp" srcSet={makeSrcSet('webp')} sizes={sizes} />
      )}
      <img
        src={base}
        alt={alt}
        className={className}
        width={width}
        height={height}
        loading={loading}
        fetchPriority={fetchPriority}
        decoding={decoding}
        onError={onError}
      />
    </picture>
  );
};

export default ResponsivePicture;
